/**
 * TypeScript port of the backend claim verifier (matchdesk.domain.verification) and its
 * registered metrics (matchdesk.domain.metrics).
 *
 * It mirrors verify_claim branch for branch: evidence binding, claim kinds, the metric
 * registry, unit checks, recomputation and the comparator, including precision-aware
 * equality. apps/web/tests/verifier.parity.test.mjs runs it on every case in
 * verifier-parity.json, generated by the real Python verifier, and requires identical
 * status, query, reason, expected and observed values. It has no imports, so Node can load
 * it directly. It does not hash evidence records; the server's evidence digest stays
 * authoritative.
 */

import { roundHalfUp } from "./precision.ts";

export { roundHalfUp };

export type Status = "verified" | "supported_inference" | "needs_revision" | "blocked";

export type Window = { period?: 1 | 2 | null; from_ms: number; to_ms: number };
export type Subject = { team_id?: string | null; player_id?: string | null };
export type Assertion = {
  metric: string;
  subject: Subject;
  window: Window;
  comparator?: "eq" | "gte" | "lte";
  value: number;
  unit: string;
  decimals?: number | null;
};
export type EventFact = {
  query: "goal_scorer.v1" | "sequence_gap.v1" | "card.v1" | "substitution.v1";
  event_id: string;
  player_id?: string | null;
  from_event_id?: string | null;
  from_tag?: string | null;
  gap_seconds?: number | null;
};
export type Claim = {
  claim_id: string;
  text: string;
  kind: "measured_stat" | "event_fact" | "tactical_inference";
  assertion?: Assertion | null;
  fact?: EventFact | null;
  evidence_event_ids: readonly string[];
};
/** Display names the prose uses, by player or team identity. */
export type Names = Readonly<Record<string, string>>;
export type Evidence = { match_id: string; event_ids: readonly string[]; window?: Window };
export type Result = {
  claim_id: string;
  status: Status;
  query_id: string;
  reason: string;
  expected: number | null;
  observed: number | null;
};

/** The fields of a match event that the registered metrics and evidence binding read. */
export type VEvent = {
  event_id: string;
  match_id: string;
  sequence: number;
  period: 1 | 2;
  match_clock_ms: number;
  type: string;
  team_id: string | null;
  player_id: string | null;
  outcome: string | null;
  xg: number | null;
  x: number | null;
  y: number | null;
  end_x: number | null;
  end_y: number | null;
  under_pressure: boolean;
  tags: readonly string[];
  /** Synthetic tracking: ball speed off a shot, the player's speed at the action, metres run since their last action. */
  shot_speed_kmh: number | null;
  player_speed_kmh: number | null;
  distance_m: number | null;
  /** The incoming player of a substitution. */
  related_player_id: string | null;
};

/** Column-oriented log, as written by matchdesk.domain.verifier_parity.compact_events. */
export type CompactLog = {
  match_ids: readonly string[];
  id: readonly string[];
  seq: readonly number[];
  period: readonly (1 | 2)[];
  ms: readonly number[];
  type: readonly string[];
  team: readonly (string | null)[];
  player: readonly (string | null)[];
  outcome: readonly (string | null)[];
  xg: readonly (number | null)[];
  x: readonly (number | null)[];
  y?: readonly (number | null)[];
  end_x: readonly (number | null)[];
  end_y?: readonly (number | null)[];
  pressure?: readonly number[];
  tags?: readonly (readonly string[])[];
  shot_speed?: readonly (number | null)[];
  player_speed?: readonly (number | null)[];
  distance?: readonly (number | null)[];
  related?: readonly (string | null)[];
};

export function expandLog(log: CompactLog): VEvent[] {
  return log.id.map((event_id, i) => ({
    event_id,
    match_id: log.match_ids[i],
    sequence: log.seq[i],
    period: log.period[i],
    match_clock_ms: log.ms[i],
    type: log.type[i],
    team_id: log.team[i],
    player_id: log.player[i],
    outcome: log.outcome[i],
    xg: log.xg[i],
    x: log.x[i],
    y: log.y ? log.y[i] : null,
    end_x: log.end_x[i],
    end_y: log.end_y ? log.end_y[i] : null,
    under_pressure: log.pressure ? log.pressure[i] === 1 : false,
    tags: log.tags ? log.tags[i] : [],
    shot_speed_kmh: log.shot_speed ? log.shot_speed[i] : null,
    player_speed_kmh: log.player_speed ? log.player_speed[i] : null,
    distance_m: log.distance ? log.distance[i] : null,
    related_player_id: log.related ? log.related[i] : null,
  }));
}

/* ---------- Metrics (matchdesk.domain.metrics) ---------- */

class MetricError extends Error {}

const FINAL_THIRD_X = 200.0 / 3.0;

export const METRIC_UNITS: Readonly<Record<string, string>> = {
  "shots.v1": "count",
  "goals.v1": "count",
  "pass_accuracy.v1": "ratio",
  "synthetic_xg.v1": "synthetic_xg",
  "final_third_entries.v1": "count",
  "possession_time.v1": "ratio",
  "pass_distance.v1": "metres",
  "progressive_passes.v1": "count",
  "pass_difficulty.v1": "rating",
  "ball_speed.v1": "km_per_hour",
  "pressured_passes.v1": "count",
  "tackles.v1": "count",
  "interceptions.v1": "count",
  "recoveries.v1": "count",
  "shot_speed.v1": "km_per_hour",
  "top_speed.v1": "km_per_hour",
  "distance_covered.v1": "kilometres",
  "sprints.v1": "count",
};

/** An action at or above this speed counts as a sprint (matchdesk.domain.metrics.SPRINT_KMH). */
export const SPRINT_KMH = 25.2;

function eventsInWindow(events: readonly VEvent[], window: Window): VEvent[] {
  if (!events.length) return [];
  const matchId = events[0].match_id;
  let previous: number | null = null;
  for (const event of events) {
    if (event.match_id !== matchId) throw new MetricError("metric input cannot mix match identities");
    if (previous !== null && event.sequence <= previous) throw new MetricError("metric input must be in strictly increasing sequence order");
    previous = event.sequence;
  }
  return events.filter((e) => (window.period == null || e.period === window.period) && window.from_ms <= e.match_clock_ms && e.match_clock_ms < window.to_ms);
}

function matchesSubject(event: VEvent, subject: Subject): boolean {
  if (subject.team_id != null && event.team_id !== subject.team_id) return false;
  if (subject.player_id != null && event.player_id !== subject.player_id) return false;
  return true;
}

function countOf(type: string) {
  return (events: readonly VEvent[], subject: Subject, window: Window) =>
    eventsInWindow(events, window).filter((e) => e.type === type && matchesSubject(e, subject)).length;
}

function passAccuracy(events: readonly VEvent[], subject: Subject, window: Window): number {
  const passes = eventsInWindow(events, window).filter((e) => e.type === "pass" && matchesSubject(e, subject));
  if (!passes.length) return 0;
  return passes.filter((e) => e.outcome === "complete").length / passes.length;
}

function syntheticXg(events: readonly VEvent[], subject: Subject, window: Window): number {
  let total = 0;
  for (const e of eventsInWindow(events, window)) if (e.type === "shot" && matchesSubject(e, subject)) total += e.xg || 0;
  return total;
}

function finalThirdEntries(events: readonly VEvent[], subject: Subject, window: Window): number {
  let count = 0;
  for (const e of eventsInWindow(events, window)) {
    if (!(e.type === "pass" || e.type === "carry" || e.type === "dribble") || e.outcome !== "complete") continue;
    if (!matchesSubject(e, subject)) continue;
    if ((e.x as number) < FINAL_THIRD_X && FINAL_THIRD_X <= (e.end_x as number)) count += 1;
  }
  return count;
}

function possessionTime(events: readonly VEvent[], subject: Subject, window: Window): number {
  if (subject.team_id == null || subject.player_id != null) throw new MetricError("possession_time.v1 requires a team-only subject");
  if (!events.length) return 0;
  eventsInWindow(events, window);
  const owned = new Map<string, number>();
  for (const period of window.period == null ? [1, 2] : [window.period]) {
    const inPeriod = events.filter((e) => e.period === period);
    for (let i = 0; i + 1 < inPeriod.length; i += 1) {
      const current = inPeriod[i];
      if (current.team_id == null) continue;
      const start = Math.max(current.match_clock_ms, window.from_ms);
      const end = Math.min(inPeriod[i + 1].match_clock_ms, window.to_ms);
      if (end <= start) continue;
      owned.set(current.team_id, (owned.get(current.team_id) ?? 0) + (end - start));
    }
  }
  let total = 0;
  for (const ms of owned.values()) total += ms;
  if (total === 0) return 0;
  return (owned.get(subject.team_id) ?? 0) / total;
}

/* Pass quality, speed and defending (matchdesk.domain.metrics). Same operations in the same order. */
const PITCH_LENGTH_M = 105.0;
const PITCH_WIDTH_M = 68.0;
const PROGRESSIVE_GAIN_M = 10.0;
const PROGRESSIVE_CLOSER = 0.25;

function metres(e: VEvent): number {
  const dx = ((e.end_x as number) - (e.x as number)) * PITCH_LENGTH_M / 100.0;
  const dy = ((e.end_y as number) - (e.y as number)) * PITCH_WIDTH_M / 100.0;
  return Math.sqrt(dx * dx + dy * dy);
}

const forwardMetres = (e: VEvent) => ((e.end_x as number) - (e.x as number)) * PITCH_LENGTH_M / 100.0;

function toGoalMetres(x: number, y: number): number {
  const dx = (100.0 - x) * PITCH_LENGTH_M / 100.0;
  const dy = (50.0 - y) * PITCH_WIDTH_M / 100.0;
  return Math.sqrt(dx * dx + dy * dy);
}

function passesOf(events: readonly VEvent[], subject: Subject, window: Window): VEvent[] {
  return eventsInWindow(events, window).filter((e) => e.type === "pass" && e.x != null && e.end_x != null && matchesSubject(e, subject));
}

function mean(values: number[]): number {
  let total = 0;
  for (const v of values) total += v;
  return values.length ? total / values.length : 0;
}

/** A 0-100 rating of one pass: 45% length, 30% forward ambition, 15% final-sixth target, 10% pressure. */
export function passDifficulty(e: VEvent): number {
  const length = Math.min(metres(e) / 40.0, 1.0);
  const ambition = Math.min(Math.max(forwardMetres(e) / 30.0, 0.0), 1.0);
  const target = (e.end_x as number) >= 500.0 / 6.0 ? 1.0 : 0.0;
  const pressure = e.under_pressure ? 1.0 : 0.0;
  return 100.0 * (0.45 * length + 0.30 * ambition + 0.15 * target + 0.10 * pressure);
}

function isProgressive(e: VEvent): boolean {
  const before = toGoalMetres(e.x as number, e.y as number);
  const after = toGoalMetres(e.end_x as number, e.end_y as number);
  return e.outcome === "complete" && forwardMetres(e) >= PROGRESSIVE_GAIN_M && after <= (1.0 - PROGRESSIVE_CLOSER) * before;
}

function ballSpeed(events: readonly VEvent[], subject: Subject, window: Window): number {
  eventsInWindow(events, window);
  const following = new Map<string, VEvent>();
  for (let i = 0; i + 1 < events.length; i += 1) if (events[i].period === events[i + 1].period) following.set(events[i].event_id, events[i + 1]);
  const speeds: number[] = [];
  for (const e of passesOf(events, subject, window)) {
    const after = following.get(e.event_id);
    if (e.outcome !== "complete" || after === undefined) continue;
    const seconds = (after.match_clock_ms - e.match_clock_ms) / 1000.0;
    if (seconds > 0) speeds.push(metres(e) / seconds * 3.6);
  }
  return mean(speeds);
}

const taggedRecoveries = (tag: string) => (events: readonly VEvent[], subject: Subject, window: Window) =>
  eventsInWindow(events, window).filter((e) => e.type === "recovery" && e.tags.includes(tag) && matchesSubject(e, subject)).length;

function shotSpeed(events: readonly VEvent[], subject: Subject, window: Window): number {
  return mean(eventsInWindow(events, window).filter((e) => e.type === "shot" && e.shot_speed_kmh != null && matchesSubject(e, subject)).map((e) => e.shot_speed_kmh as number));
}

function topSpeed(events: readonly VEvent[], subject: Subject, window: Window): number {
  let top = 0;
  for (const e of eventsInWindow(events, window)) if (e.player_speed_kmh != null && matchesSubject(e, subject) && e.player_speed_kmh > top) top = e.player_speed_kmh;
  return top;
}

function distanceCovered(events: readonly VEvent[], subject: Subject, window: Window): number {
  let metres = 0;
  for (const e of eventsInWindow(events, window)) if (e.distance_m != null && matchesSubject(e, subject)) metres += e.distance_m;
  return metres / 1000.0;
}

const sprints = (events: readonly VEvent[], subject: Subject, window: Window) =>
  eventsInWindow(events, window).filter((e) => e.player_speed_kmh != null && e.player_speed_kmh >= SPRINT_KMH && matchesSubject(e, subject)).length;

const FORMULAS: Readonly<Record<string, (events: readonly VEvent[], subject: Subject, window: Window) => number>> = {
  "pass_distance.v1": (events, subject, window) => mean(passesOf(events, subject, window).map(metres)),
  "progressive_passes.v1": (events, subject, window) => passesOf(events, subject, window).filter(isProgressive).length,
  "pass_difficulty.v1": (events, subject, window) => mean(passesOf(events, subject, window).map(passDifficulty)),
  "ball_speed.v1": ballSpeed,
  "pressured_passes.v1": (events, subject, window) => passesOf(events, subject, window).filter((e) => e.under_pressure).length,
  "tackles.v1": taggedRecoveries("tackle"),
  "interceptions.v1": taggedRecoveries("interception"),
  "recoveries.v1": countOf("recovery"),
  "shots.v1": countOf("shot"),
  "goals.v1": countOf("goal"),
  "pass_accuracy.v1": passAccuracy,
  "synthetic_xg.v1": syntheticXg,
  "final_third_entries.v1": finalThirdEntries,
  "possession_time.v1": possessionTime,
  "shot_speed.v1": shotSpeed,
  "top_speed.v1": topSpeed,
  "distance_covered.v1": distanceCovered,
  "sprints.v1": sprints,
};

export function computeMetric(metric: string, events: readonly VEvent[], subject: Subject, window: Window): number {
  const formula = Object.hasOwn(FORMULAS, metric) ? FORMULAS[metric] : undefined;
  if (!formula) throw new MetricError(`unregistered metric: ${metric}`);
  return formula(events, subject, window);
}

function comparisonPasses(comparator: string, expected: number, observed: number, decimals: number | null | undefined): boolean {
  if (comparator === "eq" && decimals != null) return roundHalfUp(observed, decimals) === roundHalfUp(expected, decimals);
  if (comparator === "eq") return Math.abs(observed - expected) <= Math.max(1e-9 * Math.max(Math.abs(observed), Math.abs(expected)), 1e-9);
  if (comparator === "gte") return observed >= expected;
  if (comparator === "lte") return observed <= expected;
  throw new Error(`unsupported comparator: ${comparator}`);
}

/* ---------- Claim text (matchdesk.domain.claim_text) ---------- */

const NUMBER_WORDS: Readonly<Record<string, number>> = {
  zero: 0, one: 1, once: 1, two: 2, twice: 2, both: 2, brace: 2, double: 2, three: 3, thrice: 3,
  "hat-trick": 3, "hat trick": 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
  eleven: 11, twelve: 12,
};
const escapeRegExp = (text: string) => text.replace(/[.*+?^${}()|[\]\\\-]/g, "\\$&");
const B = "(?<![A-Za-z0-9_])";
const E = "(?![A-Za-z0-9_])";
const WORDS = new RegExp(`${B}(${Object.keys(NUMBER_WORDS).sort((a, b) => b.length - a.length).map(escapeRegExp).join("|")})${E}`, "g");
const CLOCK = /[0-9]{1,3}:[0-9]{2}/g;
const SCORELINE = new RegExp(`${B}[0-9]+\\s*[-–—]\\s*[0-9]+${E}`, "g");
const MINUTE = new RegExp(`${B}[0-9]+\\s*(?:'|′|’|(?:st|nd|rd|th|mins?|minutes?)${E})`, "g");
const PERCENT = new RegExp(`${B}([0-9]+(?:\\.[0-9]+)?)\\s*(?:%|per\\s?cent${E})`, "g");
const DIGITS = new RegExp(`${B}[0-9]+(?:\\.[0-9]+)?${E}`, "g");
// Identifiers such as E-1366, nbr-09 or CL-0214 name a record; they state no quantity.
const IDENTIFIER = new RegExp(`${B}[a-z]+-[0-9]+${E}`, "g");
export const TEXT_QUERY_ID = "claim-text-binding-v1";

/** The counts and percentages a sentence states, ignoring clocks, scorelines, minutes and IDs. */
export function statedQuantities(text: string): { counts: number[]; percents: number[] } {
  let lowered = text.toLowerCase().replace(/’/g, "'");
  lowered = lowered.replace(IDENTIFIER, " ").replace(CLOCK, " ").replace(SCORELINE, " ");
  const percents = [...lowered.matchAll(PERCENT)].map((m) => Number(m[1]));
  lowered = lowered.replace(PERCENT, " ").replace(MINUTE, " ");
  const counts = [...lowered.matchAll(DIGITS)].map((m) => Number(m[0]));
  for (const m of lowered.matchAll(WORDS)) counts.push(NUMBER_WORDS[m[1]]);
  return { counts, percents };
}

// Units stated as a plain number at one decimal place unless the assertion says otherwise.
const MEASURE_UNITS: ReadonlySet<string> = new Set(["metres", "km_per_hour", "rating", "per_minute", "kilometres"]);

function expectedQuantity(claim: Claim): ["count" | "percent", number] | null {
  const assertion = claim.assertion;
  if (assertion) {
    if (assertion.unit === "count") return ["count", assertion.value];
    if (assertion.unit === "ratio") {
      const places = assertion.decimals == null ? 6 : Math.max(assertion.decimals - 2, 0);
      return ["percent", Number(roundHalfUp(assertion.value * 100, places))];
    }
    if (assertion.unit === "synthetic_xg") return ["count", Number(roundHalfUp(assertion.value, assertion.decimals ?? 2))];
    if (MEASURE_UNITS.has(assertion.unit)) return ["count", Number(roundHalfUp(assertion.value, assertion.decimals ?? 1))];
    return null;
  }
  if (claim.fact && claim.fact.gap_seconds != null) return ["count", claim.fact.gap_seconds];
  return null;
}

function subjectId(claim: Claim): string | null {
  if (claim.assertion) return claim.assertion.subject.player_id || claim.assertion.subject.team_id || null;
  if (claim.fact) return claim.fact.player_id ?? null;
  return null;
}

const NEGATION = new RegExp(`${B}(?:not|no|never|none|neither|nor|without|failed to|fails to|[a-z]+n't|cannot)${E}`);
// The words that name each registered statistic; longer phrases are matched first and masked.
const METRIC_WORDS: readonly (readonly [string, string])[] = [
  ["synthetic_xg.v1", "expected goals|xg"],
  ["final_third_entries.v1", "final[- ]third"],
  ["possession_time.v1", "possession|of the ball"],
  ["pass_difficulty.v1", "pass(?:ing)? difficulty|difficulty(?: rating)?"],
  ["pass_distance.v1", "pass(?:es|ing)? (?:length|distance)|metres|meters"],
  ["progressive_passes.v1", "progressive pass(?:es)?"],
  ["pressured_passes.v1", "pass(?:es)? under pressure|pressured pass(?:es)?"],
  // Synthetic tracking; the unit is part of the phrase, so it is masked with it.
  ["shot_speed.v1", "shot speed(?: of| was)? [0-9.]+ km/h|shot speed"],
  ["top_speed.v1", "top speed(?: of| was)? [0-9.]+ km/h|top speed"],
  ["distance_covered.v1", "(?:covered|ran) [0-9.]+ (?:km|kilometres)|distance covered"],
  ["sprints.v1", "sprints?"],
  ["ball_speed.v1", "ball speed|km/h|speed"],
  ["tackles.v1", "tackles?|tackled"],
  ["interceptions.v1", "interceptions?|intercepted"],
  ["recoveries.v1", "ball recover(?:y|ies)|recover(?:y|ies|ed)|won the ball back"],
  ["pass_accuracy.v1", "pass(?:es|ing)?"],
  ["shots.v1", "shots?|attempts?|efforts?"],
  ["goals.v1", "goals?|scor(?:ed|es|ing)|brace|hat[- ]trick|netted|scoresheet"],
];
// Details of a goal or set piece the event log records only as tags, if at all.
const DETAILS: readonly (readonly [string, string])[] = [
  ["penalty", "penalt(?:y|ies)|spot[- ]kick"],
  ["header", "headers?|headed|heads? (?:in|home)"],
  ["free_kick", "free[- ]kicks?"],
  ["corner", "corners?"],
  ["throw_in", "throw[- ]ins?"],
  ["own_goal", "own[- ]goals?"],
  ["volley", "volley(?:ed|s)?"],
  ["left_foot", "left[- ]foot(?:ed)?|left foot"],
  ["right_foot", "right[- ]foot(?:ed)?|right foot"],
  ["outside_box", "outside the (?:box|area)|from (?:distance|range)|long[- ]range"],
  ["inside_box", "inside the (?:box|area)|tap[- ]ins?"],
  ["counter", "counter[- ]attack"],
];
const MINUTE_MARK = "([0-9]{1,3})(?:'|\u2032|\u2019)";
const WINDOW_FIRST = new RegExp(`${B}(?:first|1st|opening)[- ]half${E}|before (?:half[- ]?time|the break)`);
const WINDOW_SECOND = new RegExp(`${B}(?:second|2nd)[- ]half${E}|after (?:half[- ]?time|the break)`);
const WINDOW_BETWEEN = new RegExp(`${B}between ([0-9]{1,3})(?:'|\u2032|\u2019| minutes?)? and ([0-9]{1,3})(?:'|\u2032|\u2019| minutes?)?`);
const WINDOW_FROM = new RegExp(`${B}(?:since|after|from) ${MINUTE_MARK}`);
const WINDOW_TO = new RegExp(`${B}(?:before|by|until|up to) ${MINUTE_MARK}`);
const WINDOW_TO_CLOCK = new RegExp(`${B}(?:before|by|until|up to) ([0-9]{1,3}):([0-9]{2})`);
const WINDOW_LAST = new RegExp(`${B}(?:last|final) ([0-9]{1,3}) minutes?${E}`);
const FACT_MINUTE = new RegExp(`${B}([0-9]{1,3})(?:'|\u2032|\u2019|(?:st|nd|rd|th) minute)`, "g");
const GOAL_WORDS = new RegExp(`${B}(?:goals?|scor(?:ed|es|ing)|netted|(?:headed|nodded|fired|slotted|tapped|poked|swept|curled|volleyed|turned) (?:in|home))${E}`);
const CARD_WORDS = new RegExp(`${B}(?:cards?|booked|booking|cautioned|sent off|dismissed)${E}`);
const RED_WORDS = new RegExp(`${B}(?:red|sent off|dismissed|second yellow)${E}`);
const YELLOW_WORDS = new RegExp(`${B}(?:yellow|booked|booking|cautioned)${E}`);
const SUB_PASSIVE = new RegExp(`${B}(?:replaced by|substituted by|off for)${E}`);
const SUB_WORDS = new RegExp(`${B}(?:replaced|replaces|substitut(?:ed|es|ion)|comes on|came on|on for|off for)${E}`);
const MINUTE_MS = 60_000;
const word = (words: string) => new RegExp(`${B}(?:${words})${E}`);

const lowerText = (text: string) => text.toLowerCase().replace(/’/g, "'").replace(IDENTIFIER, " ");
const namesSubject = (text: string, name: string) => new RegExp(B + escapeRegExp(name.toLowerCase()) + E).test(text.toLowerCase());
const namePosition = (text: string, name: string) => text.toLowerCase().search(new RegExp(B + escapeRegExp(name.toLowerCase()) + E));

function metricsNamed(lowered: string): string[] {
  const found: string[] = [];
  for (const [metric, words] of METRIC_WORDS) {
    const pattern = new RegExp(`${B}(?:${words})${E}`, "g");
    if (pattern.test(lowered)) {
      found.push(metric);
      lowered = lowered.replace(pattern, " ");
    }
  }
  return found;
}

function windowProblem(lowered: string, window: Window): string | null {
  let stated = false;
  const differs = "Claim text states a time window that differs from its assertion";
  if (WINDOW_FIRST.test(lowered)) { stated = true; if (window.period !== 1) return differs; }
  if (WINDOW_SECOND.test(lowered)) { stated = true; if (window.period !== 2) return differs; }
  const between = WINDOW_BETWEEN.exec(lowered);
  if (between) {
    stated = true;
    if (window.from_ms !== Number(between[1]) * MINUTE_MS || window.to_ms !== Number(between[2]) * MINUTE_MS) return differs;
  } else {
    const start = WINDOW_FROM.exec(lowered);
    if (start) { stated = true; if (window.from_ms !== Number(start[1]) * MINUTE_MS) return differs; }
    const end = WINDOW_TO.exec(lowered);
    if (end) { stated = true; if (window.to_ms !== Number(end[1]) * MINUTE_MS) return differs; }
    const clock = WINDOW_TO_CLOCK.exec(lowered);
    if (clock) { stated = true; if (window.to_ms !== (Number(clock[1]) * 60 + Number(clock[2])) * 1000) return differs; }
  }
  const last = WINDOW_LAST.exec(lowered);
  if (last) { stated = true; if (window.to_ms - window.from_ms !== Number(last[1]) * MINUTE_MS) return differs; }
  if (!stated && (window.period != null || window.from_ms !== 0)) return "Claim text does not state its time window";
  return null;
}

function clockText(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
}

const teamOf = (playerId: string, events: readonly VEvent[]) => events.find((e) => e.player_id === playerId)?.team_id ?? null;

function teamProblem(lowered: string, team: string | null, names: Names, teams: readonly string[]): string | null {
  for (const teamId of teams) {
    const name = Object.hasOwn(names, teamId) ? names[teamId] : undefined;
    if (name && teamId !== team && namesSubject(lowered, name)) return "Claim text names a team the claim is not about";
  }
  return null;
}

/** The shot a goal was scored from: the scorer's goal-bound shot logged just before it. */
function scoringShot(goal: VEvent, events: readonly VEvent[]): VEvent | null {
  return events.find((e) => e.sequence === goal.sequence - 1 && e.type === "shot" && e.outcome === "goal" && e.player_id === goal.player_id) ?? null;
}

function factProblem(claim: Claim, lowered: string, events: readonly VEvent[], names?: Names | null): string | null {
  const fact = claim.fact;
  if (!fact) return null;
  const byId = new Map(events.map((e) => [e.event_id, e]));
  const cited = [fact.from_event_id, fact.event_id].filter((id): id is string => id != null && byId.has(id)).map((id) => byId.get(id) as VEvent);
  if (!cited.length) return null;
  const clocks = new Set(cited.map((e) => clockText(e.match_clock_ms)));
  for (const found of lowered.match(CLOCK) ?? []) {
    if (!clocks.has(found.padStart(5, "0"))) return "Claim text states a time that differs from its cited events";
  }
  const minutes = new Set<number>();
  for (const e of cited) { const m = Math.floor(e.match_clock_ms / MINUTE_MS); minutes.add(m); minutes.add(m + 1); }
  for (const found of lowered.replace(CLOCK, " ").matchAll(FACT_MINUTE)) {
    if (!minutes.has(Number(found[1]))) return "Claim text states a time that differs from its cited events";
  }
  const tags = new Set(cited.flatMap((e) => e.tags));
  for (const e of cited) {
    const shot = e.type === "goal" ? scoringShot(e, events) : null;
    if (shot) for (const tag of shot.tags) tags.add(tag);
  }
  for (const [detail, words] of DETAILS) {
    if (word(words).test(lowered) && !tags.has(detail) && !(detail === "corner" && fact.from_tag === "corner")) {
      return "Claim text states a detail the event log does not record";
    }
  }
  if (fact.query === "goal_scorer.v1" && !GOAL_WORDS.test(lowered)) return "Claim text does not say this was a goal";
  const target = events.find((e) => e.event_id === fact.event_id);
  if (fact.query === "card.v1" && target) {
    if (!CARD_WORDS.test(lowered)) return "Claim text does not say this was a card";
    const saysRed = RED_WORDS.test(lowered);
    const saysYellow = YELLOW_WORDS.test(lowered);
    // A yellow must read as a yellow; a red or second yellow must read as a sending-off.
    if (target.outcome === "yellow" && (saysRed || !saysYellow)) return "Claim text states a card colour the event log does not record";
    if (target.outcome === "red" && (saysYellow || !saysRed)) return "Claim text states a card colour the event log does not record";
    if (target.outcome === "second_yellow" && !saysRed) return "Claim text states a card colour the event log does not record";
  }
  if (fact.query === "substitution.v1" && target) {
    if (!SUB_WORDS.test(lowered)) return "Claim text does not say this was a substitution";
    const incoming = names && target.related_player_id ? names[target.related_player_id] : undefined;
    if (incoming === undefined || !namesSubject(lowered, incoming)) return "Claim text does not name the incoming player";
    const outgoing = names && target.player_id ? names[target.player_id] : undefined;
    if (outgoing !== undefined && namesSubject(lowered, outgoing)) {
      // "A replaced B" and "A came on for B" put the incoming player first; "B was replaced by A" and "B off for A" second.
      const first = namePosition(lowered, incoming) < namePosition(lowered, outgoing);
      if (first === SUB_PASSIVE.test(lowered)) return "Claim text has the substitution the wrong way round";
    }
  }
  return null;
}

/** Why the sentence does not match its structured claim, or null if it does. */
export function textBindingProblem(claim: Claim, names?: Names | null, events: readonly VEvent[] = []): string | null {
  const expected = expectedQuantity(claim);
  if (expected) {
    const [kind, value] = expected;
    const stated = statedQuantities(claim.text);
    const found = kind === "count" ? stated.counts : stated.percents;
    if (found.some((q) => q !== value)) return "Claim text states a quantity that differs from its assertion";
    if (names && !found.includes(value)) return "Claim text does not state the asserted value";
  }
  if (!names) return null;
  const subject = subjectId(claim);
  if (subject != null) {
    const name = Object.hasOwn(names, subject) ? names[subject] : undefined;
    if (name === undefined) return "Claim subject has no registered display name";
    if (!namesSubject(claim.text, name)) return "Claim text does not name the asserted subject";
  }
  const lowered = lowerText(claim.text);
  const teams = [...new Set(events.map((e) => e.team_id).filter((t): t is string => t != null))].sort();
  if (NEGATION.test(lowered)) return "Claim text negates its statement; negative claims are not checked";
  if (claim.assertion) {
    const assertion = claim.assertion;
    const named = metricsNamed(lowered);
    if (!named.includes(assertion.metric)) return "Claim text does not name the asserted statistic";
    if (named.length > 1) return "Claim text names a statistic other than the asserted one";
    const asserted = assertion.subject;
    const team = asserted.team_id || (asserted.player_id ? teamOf(asserted.player_id, events) : null);
    const problem = teamProblem(lowered, team, names, teams) ?? windowProblem(lowered, assertion.window);
    if (problem) return problem;
    if (DETAILS.some(([, words]) => word(words).test(lowered))) return "Claim text states a detail the registered metric does not measure";
    return null;
  }
  if (claim.fact) {
    const target = events.find((e) => e.event_id === claim.fact?.event_id);
    return teamProblem(lowered, target ? target.team_id : null, names, teams) ?? factProblem(claim, lowered, events, names);
  }
  return null;
}

/* ---------- Verification (matchdesk.domain.verification) ---------- */

const queryId = (metric: string) => `metric-${metric.replace(/\./g, "-")}`;
const COUNTED_TYPES: Readonly<Record<string, string>> = { "goals.v1": "goal", "shots.v1": "shot" };

function validateEvidence(claim: Claim, evidence: Evidence, events: readonly VEvent[]): string | null {
  if (!events.length) return "No accepted events are available for verification";
  if (events.some((e) => e.match_id !== evidence.match_id)) return "Verification input contains events outside the evidence match";
  const eventIds = new Set(events.map((e) => e.event_id));
  const recordIds = new Set(evidence.event_ids);
  if (claim.evidence_event_ids.some((id) => !recordIds.has(id))) return "Claim cites events that are not bound by the evidence record";
  if (claim.evidence_event_ids.some((id) => !eventIds.has(id))) return "Claim cites events that are not present in accepted event input";
  return null;
}

type FactOutcome = [Status, string, string, number | null, number | null];

/** One registered event-fact query; a wrong gap carries the stated and recorded seconds. */
function factResult(claim: Claim, fact: EventFact, evidence: Evidence, events: readonly VEvent[]): FactOutcome {
  const query = "event-" + fact.query.replace(/\./g, "-").replace(/_/g, "-");
  const referenced = fact.from_event_id == null ? [fact.event_id] : [fact.from_event_id, fact.event_id];
  if (referenced.some((id) => !claim.evidence_event_ids.includes(id))) return ["blocked", query, "Event fact reads events the claim does not cite", null, null];
  const byId = new Map(events.map((e) => [e.event_id, e]));
  const target = byId.get(fact.event_id) as VEvent;
  if (evidence.window && target.match_clock_ms >= evidence.window.to_ms) return ["blocked", query, "Event fact reads events after the evidence window", null, null];
  if (fact.query === "card.v1" || fact.query === "substitution.v1") {
    const kind = fact.query === "card.v1" ? "card" : "substitution";
    return target.type === kind && target.player_id === fact.player_id
      ? ["verified", query, `The cited ${kind} event records the stated player`, null, null]
      : ["needs_revision", query, `The cited event is not a ${kind} for the stated player`, null, null];
  }
  if (fact.query === "goal_scorer.v1") {
    return target.type === "goal" && target.player_id === fact.player_id
      ? ["verified", query, "The cited goal event records the stated scorer", null, null]
      : ["needs_revision", query, "The cited event is not a goal by the stated player", null, null];
  }
  const earlier = byId.get(fact.from_event_id as string) as VEvent;
  if (earlier.sequence >= target.sequence) return ["needs_revision", query, "The cited events are not in the stated order", null, null];
  if (fact.from_tag != null && !earlier.tags.includes(fact.from_tag)) return ["needs_revision", query, `The earlier event is not tagged ${fact.from_tag}`, null, null];
  const gap = Number(roundHalfUp((target.match_clock_ms - earlier.match_clock_ms) / 1000, 0));
  if (gap !== fact.gap_seconds) return ["needs_revision", query, "The recorded gap differs from the stated seconds", fact.gap_seconds as number, gap];
  return ["verified", query, "The recorded events and gap match the stated sequence", null, null];
}

function citesCountedEvents(claim: Claim, assertion: Assertion, events: readonly VEvent[], type: string): boolean {
  const { window, subject } = assertion;
  const counted = new Set(events.filter((e) => e.type === type
    && (window.period == null || e.period === window.period)
    && window.from_ms <= e.match_clock_ms && e.match_clock_ms < window.to_ms
    && (subject.team_id == null || e.team_id === subject.team_id)
    && (subject.player_id == null || e.player_id === subject.player_id)).map((e) => e.event_id));
  if (counted.size) return claim.evidence_event_ids.every((id) => counted.has(id));
  // Nothing to count: a zero cites the window it read, so every cited event must lie in it.
  const inside = new Set(events.filter((e) => (window.period == null || e.period === window.period)
    && window.from_ms <= e.match_clock_ms && e.match_clock_ms < window.to_ms).map((e) => e.event_id));
  return claim.evidence_event_ids.every((id) => inside.has(id));
}

/** Verify one claim against evidence and accepted events, exactly as the backend does. */
export function verifyClaim(claim: Claim, evidence: Evidence, events: readonly VEvent[], names?: Names | null): Result {
  const base = { claim_id: claim.claim_id, expected: null, observed: null };
  const blocking = validateEvidence(claim, evidence, events);
  if (blocking) return { ...base, status: "blocked", query_id: "evidence-binding-v1", reason: blocking };
  if (claim.assertion && evidence.window && claim.assertion.window.to_ms > evidence.window.to_ms) {
    return { ...base, status: "blocked", query_id: "evidence-window-v1", reason: "Claim window extends past the evidence window" };
  }
  if (claim.kind === "tactical_inference") {
    return { ...base, status: "supported_inference", query_id: "evidence-support-v1", reason: "All cited evidence events exist; tactical meaning remains an inference" };
  }
  if (claim.kind === "event_fact" && claim.fact) {
    let [status, query_id, reason, expected, observed] = factResult(claim, claim.fact, evidence, events);
    if (status === "verified") {
      const problem = textBindingProblem(claim, names, events);
      if (problem) [status, query_id, reason] = ["needs_revision", TEXT_QUERY_ID, problem];
    }
    return { ...base, status, query_id, reason, expected, observed };
  }
  if (claim.kind === "event_fact") {
    return { ...base, status: "needs_revision", query_id: "event-fact-semantic-v1", reason: "Event-fact prose has no registered semantic assertion; evidence existence alone cannot verify the text" };
  }
  const assertion = claim.assertion;
  if (!assertion) throw new Error("Measured claim is missing its required metric assertion");
  const unit = Object.hasOwn(METRIC_UNITS, assertion.metric) ? METRIC_UNITS[assertion.metric] : undefined;
  if (unit === undefined) return { ...base, status: "blocked", query_id: "metric-registry-v1", reason: `Metric is not registered: ${assertion.metric}` };
  if (assertion.unit !== unit) {
    return { ...base, status: "blocked", query_id: queryId(assertion.metric), reason: `Claim unit ${assertion.unit} does not match registered metric unit ${unit}` };
  }
  let observed: number;
  try {
    observed = computeMetric(assertion.metric, events, assertion.subject, assertion.window);
  } catch (error) {
    if (!(error instanceof MetricError)) throw error;
    return { ...base, status: "blocked", query_id: queryId(assertion.metric), reason: `Metric recomputation failed: ${error.message}`, expected: assertion.value };
  }
  let passed = comparisonPasses(assertion.comparator ?? "eq", assertion.value, observed, assertion.decimals);
  let query_id = queryId(assertion.metric);
  let reason = passed ? "Registered metric recomputation satisfies the claim comparator" : "Registered metric recomputation does not satisfy the claim comparator";
  const countedType = Object.hasOwn(COUNTED_TYPES, assertion.metric) ? COUNTED_TYPES[assertion.metric] : undefined;
  if (passed && countedType !== undefined && !citesCountedEvents(claim, assertion, events, countedType)) {
    passed = false;
    reason = "Claim cites events the registered metric does not count";
  }
  if (passed) {
    const problem = textBindingProblem(claim, names, events);
    if (problem) { passed = false; query_id = TEXT_QUERY_ID; reason = problem; }
  }
  return { claim_id: claim.claim_id, status: passed ? "verified" : "needs_revision", query_id, reason, expected: assertion.value, observed };
}
